import { test, expect } from '@playwright/test'

test("settings-privacy", async ({ page }) => {
  // Open Settings, then open the Privacy section. Stop when the privacy settings are shown.
  await page.goto("/", { waitUntil: 'domcontentloaded' })
  await expect(async () => {
    await page.getByRole("button", { name: "Settings", exact: true }).click()
    await expect(page.getByRole("button", { name: "Privacy", exact: true })).toBeVisible({ timeout: 2000 })
  }).toPass({ timeout: 20000 })
  await expect(async () => {
    await page.getByRole("button", { name: "Privacy", exact: true }).click()
    await expect(page).toHaveURL(new RegExp("/settings/privacy"), { timeout: 2000 })
  }).toPass({ timeout: 20000 })
  await expect(page).toHaveURL(new RegExp("/settings/privacy"))
})
